        pos = name.indexOf(QLatin1Char('/'));   // look again
    }
    if (pos != -1) {
        const QString left = name.left(pos);
        const QString right = name.mid(pos + 1);

        //qCDebug(KArchiveLog) << "left=" << left << "right=" << right;

        const KArchiveEntry *e = d->entries.value(left);
        if (!e || !e->isDirectory()) {
            return nullptr;
